import{_ as l,a0 as p,w as o,s as r,ao as d,I as i,x as s,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 文件系統中使用 attr 添加擴展屬性 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 文件系統中使用 attr 添加擴展屬性 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 文件系統中使用 attr 添加擴展屬性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 文件系統中使用 attr 添加擴展屬性 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20220620 How I use the attr command with my Linux filesystem","title":"在 Linux 文件系統中使用 attr 添加擴展屬性","tag":"202309","desc":""},"relativePath":"202309/20220620 How I use the attr command with my Linux filesystem.md","filePath":"[post].md"}'),c={name:"202309/20220620 How I use the attr command with my Linux filesystem.md"};function h(u,a,g,f,m,b){const e=p("Link");return o(),r("div",null,[a[15]||(a[15]=d(`<h1 id="在-linux-文件系統中使用-attr-添加擴展屬性" tabindex="-1">在 Linux 文件系統中使用 attr 添加擴展屬性 <a class="header-anchor" href="#在-linux-文件系統中使用-attr-添加擴展屬性" aria-label="Permalink to “在 Linux 文件系統中使用 attr 添加擴展屬性”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/15/081240syst7uisttadnky6.jpg" alt=""></p><blockquote><p>我使用開源的 XFS 文件系統是為了其擴展屬性帶來的小小便利。擴展屬性是一種為我的數據添加上下文的獨特方式。</p></blockquote><p>“文件系統” 是一個描述你的計算機怎樣跟蹤你創建的所有文件的完美詞語。你的計算機存儲有大量的數據，無論是文檔、配置文件還是數以千計的照片。這需要一種對人和機器都友好的方式。諸如 Ext4、XFS、JFS、BtrFS 的文件系統是你的計算機用來跟蹤文件的“語言”。</p><p>你的桌面或終端可以幫助你快速查找文件。例如，你的文件管理器可能有過濾功能，以便讓你可以快速查看家目錄內的圖片，它也可能帶有搜索功能以讓你使用文件名定位文件。這些特性被稱作<em>文件屬性</em>，正如其名，它們是由文件頭或者文件系統代碼定義的文件對象的屬性。大多數的文件系統記錄了標準的文件屬性，例如文件名、文件大小、文件類型、創建時間、上次訪問時間等。</p><p>我在我的計算機上使用開源的 XFS 文件系統，不是為了其穩定性和高性能，而是為了其擴展屬性帶來的小小便利。</p><h3 id="常見的文件屬性" tabindex="-1">常見的文件屬性 <a class="header-anchor" href="#常見的文件屬性" aria-label="Permalink to “常見的文件屬性”">​</a></h3><p>當你保存一個文件，文件相關的數據也會隨同保存。常見的屬性會告訴操作系統是否更新訪問時間，什麼時間同步數據到硬盤等邏輯細節。哪些屬性被保存取決於底層文件系統的功能和特性。</p><p>在標準文件屬性（如果有標準屬性的話）之外，XFS、Ext4 和 BtrFS 文件系統都可以使用擴展屬性。</p><h3 id="擴展屬性" tabindex="-1">擴展屬性 <a class="header-anchor" href="#擴展屬性" aria-label="Permalink to “擴展屬性”">​</a></h3><p>XFS、Ext4 和 BtrFs 允許你創建自己的任意文件屬性。由於是自己創建的，操作系統不會有內建支持，不過我以“標籤”的方式使用它們，就像圖片的 EXIF 數據一樣。開發者們也許會選擇使用擴展屬性去開發應用內的自定義的功能。</p><p>XFS 中的屬性有兩個“命名空間”：用户（<code>user</code>）和根（<code>root</code>）。當創建屬性時，你必須將其加入其中一個命名空間。要將屬性添加到根命名空間，必須使用 <code>sudo</code> 命令或以 <code>root</code> 身份登錄。</p><h3 id="增加一個屬性" tabindex="-1">增加一個屬性 <a class="header-anchor" href="#增加一個屬性" aria-label="Permalink to “增加一個屬性”">​</a></h3><p>你可以使用 <code>attr</code> 和 <code>setfattr</code> 命令在 XFS 文件系統中為文件增加屬性。</p><p><code>attr</code> 命令默認在 <code>user</code> 命名空間下進行，所以你只需要為屬性設置一個名字（<code>-s</code>）和值（<code>-V</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ attr -s flavor -V vanilla example.txt</span></span>
<span class="line"><span>Attribute &quot;flavor&quot; set to a 7 byte value for example.txt:</span></span>
<span class="line"><span>vanilla</span></span></code></pre></div><p><code>setfattr</code> 命令需要你指定目標命名空間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ setfattr --name user.flavor --value chocolate example.txt</span></span></code></pre></div><h3 id="列出擴展文件屬性" tabindex="-1">列出擴展文件屬性 <a class="header-anchor" href="#列出擴展文件屬性" aria-label="Permalink to “列出擴展文件屬性”">​</a></h3><p>使用 <code>attr</code> 或者 <code>getfattr</code> 命令可以看已添加到文件上的擴展屬性。<code>attr</code> 命令默認使用 <code>user</code> 空間，使用 <code>-g</code> 以獲取擴展屬性：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ attr -g flavor example.txt</span></span>
<span class="line"><span>Attribute &quot;flavor&quot; had a 9 byte value for example.txt:</span></span>
<span class="line"><span>chocolate</span></span></code></pre></div><p><code>getfattr</code> 命令需要屬性的命名空間和名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getfattr --name user.flavor example.txt </span></span>
<span class="line"><span># file: example.txt</span></span>
<span class="line"><span>user.flavor=&quot;chocolate&quot;</span></span></code></pre></div><h3 id="列出所有擴展屬性" tabindex="-1">列出所有擴展屬性 <a class="header-anchor" href="#列出所有擴展屬性" aria-label="Permalink to “列出所有擴展屬性”">​</a></h3><p>要看一個文件的所有擴展屬性，你可以使用 <code>attr -l</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ attr -l example.txt</span></span>
<span class="line"><span>Attribute &quot;md5sum&quot; has a 32 byte value for example.txt</span></span>
<span class="line"><span>Attribute &quot;flavor&quot; has a 9 byte value for example.txt</span></span></code></pre></div><p>或者，你也可以使用 <code>getfattr -d</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getfattr -d example.txt</span></span>
<span class="line"><span># file: example.txt</span></span>
<span class="line"><span>user.flavor=&quot;chocolate&quot;</span></span>
<span class="line"><span>user.md5sum=&quot;969181e76237567018e14fe1448dfd11&quot;</span></span></code></pre></div><p>擴展文件屬性可以使用 <code>attr</code> 和 <code>setfattr</code> 更新，就像你創建這些屬性一樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ setfattr --name user.flavor --value strawberry example.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ getfattr -d example.txt</span></span>
<span class="line"><span># file: example.txt</span></span>
<span class="line"><span>user.flavor=&quot;strawberry&quot;</span></span>
<span class="line"><span>user.md5sum=&quot;969181e76237567018e14fe1448dfd11&quot;</span></span></code></pre></div><h3 id="其他文件系統上的屬性" tabindex="-1">其他文件系統上的屬性 <a class="header-anchor" href="#其他文件系統上的屬性" aria-label="Permalink to “其他文件系統上的屬性”">​</a></h3><p>使用擴展屬性最大的風險是忘記這些屬性是特定於某個文件系統的。這意味着當你從一個磁盤或分區複製文件到另外一個磁盤或分區時，這些屬性都會丟失，<strong>即使</strong>目標位置的文件系統也支持擴展屬性。</p><p>為了避免丟失擴展屬性，你需要使用支持保留這些屬性的工具，例如 <code>rsync</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync --archive --xattrs ~/example.txt /tmp/</span></span></code></pre></div><p>但無論你使用什麼工具，如果你傳輸文件到一個不知道如何處理擴展屬性的文件系統，這些屬性都會被丟棄。</p><h3 id="搜索屬性" tabindex="-1">搜索屬性 <a class="header-anchor" href="#搜索屬性" aria-label="Permalink to “搜索屬性”">​</a></h3><p>與擴展屬性交互的機制並不多，所以使用這些添加的文件屬性的方法也有限。我使用擴展屬性作為標籤機制，這讓我可以將沒有明顯關係的文件聯繫起來。例如，假設我需要在一個項目中用“知識共享”的圖形。假如我預見性地將 <code>license</code> 屬性添加到了我的圖形庫中，我就可以使用 <code>find</code> 和 <code>getfattr</code> 在圖形文件夾中尋找：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~/Graphics/ -type f \\</span></span>
<span class="line"><span>    -exec getfattr \\</span></span>
<span class="line"><span>    --name user.license \\</span></span>
<span class="line"><span>    -m cc-by-sa {} \\; 2&gt;/dev/null</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file: /home/tux/Graphics/Linux/kde-eco-award.png</span></span>
<span class="line"><span>user.license=&quot;cc-by-sa&quot;</span></span>
<span class="line"><span>user.md5sum=&quot;969181e76237567018e14fe1448dfd11&quot;</span></span></code></pre></div><h3 id="文件系統的秘密" tabindex="-1">文件系統的秘密 <a class="header-anchor" href="#文件系統的秘密" aria-label="Permalink to “文件系統的秘密”">​</a></h3><p>文件系統一般不會引起你的注意。它們實際是定義文件的系統。這不是計算機做的最讓人興奮的任務，也不是用户應該關心的東西。但是有些文件系統可以給你有趣、安全的特殊能力，擴展文件屬性就是一個好例子。它的用途可能有限，但是擴展屬性是你為數據增加上下文的獨特方法。</p><p><em>（題圖：MJ/06c0c478-7af7-49e4-836b-a9923db9dc0c）</em></p><hr>`,42)),i("p",null,[a[1]||(a[1]=s("via: ",-1)),t(e,{href:"https://opensource.com/article/22/6/linux-attr-command"},{default:n(()=>[...a[0]||(a[0]=[s("https://opensource.com/article/22/6/linux-attr-command",-1)])]),_:1})]),i("p",null,[a[6]||(a[6]=s("作者：",-1)),t(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[2]||(a[2]=[s("Seth Kenlon",-1)])]),_:1}),a[7]||(a[7]=s(" 選題：",-1)),t(e,{href:"https://github.com/lkxed"},{default:n(()=>[...a[3]||(a[3]=[s("lkxed",-1)])]),_:1}),a[8]||(a[8]=s(" 譯者：",-1)),t(e,{href:"https://github.com/wznmickey"},{default:n(()=>[...a[4]||(a[4]=[s("wznmickey",-1)])]),_:1}),a[9]||(a[9]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...a[11]||(a[11]=[s("Linux中國",-1)])]),_:1}),a[14]||(a[14]=s(" 榮譽推出",-1))])])}const v=l(c,[["render",h]]);export{y as __pageData,v as default};
